import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { insightsBulkSetTestAccountFilterCreate } from 'products/product_analytics/frontend/generated/api'
import { InsightBulkSetTestAccountFilterResponseApi } from 'products/product_analytics/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface applyTestAccountFilterLogicValues {
    currentProjectId: number | string // teamLogic
    pendingEnabled: boolean | null
    bulkSetResponse: InsightBulkSetTestAccountFilterResponseApi | null
    bulkSetResponseLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface applyTestAccountFilterLogicActions {
    applyToExistingInsights: (enabled: boolean) => {
        enabled: boolean
    }
    applyToExistingInsightsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    applyToExistingInsightsSuccess: (
        bulkSetResponse: InsightBulkSetTestAccountFilterResponseApi,
        payload?: {
            enabled: boolean
        }
    ) => {
        bulkSetResponse: InsightBulkSetTestAccountFilterResponseApi
        payload?: {
            enabled: boolean
        }
    }
}

export type applyTestAccountFilterLogicType = MakeLogicType<
    applyTestAccountFilterLogicValues,
    applyTestAccountFilterLogicActions
>

export const applyTestAccountFilterLogic = kea<applyTestAccountFilterLogicType>([
    path(['scenes', 'settings', 'environment', 'applyTestAccountFilterLogic']),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),
    actions({
        applyToExistingInsights: (enabled: boolean) => ({ enabled }),
    }),
    reducers({
        pendingEnabled: [
            null as boolean | null,
            {
                applyToExistingInsights: (_, { enabled }) => enabled,
                applyToExistingInsightsSuccess: () => null,
                applyToExistingInsightsFailure: () => null,
            },
        ],
    }),
    loaders(({ values }) => ({
        bulkSetResponse: [
            null as InsightBulkSetTestAccountFilterResponseApi | null,
            {
                applyToExistingInsights: async ({ enabled }: { enabled: boolean }) => {
                    return await insightsBulkSetTestAccountFilterCreate((values.currentProjectId ?? '').toString(), {
                        enabled,
                    })
                },
            },
        ],
    })),
    listeners(() => ({
        applyToExistingInsightsSuccess: ({ bulkSetResponse, payload }) => {
            if (!bulkSetResponse) {
                return
            }
            const { updated, unsupported, skipped } = bulkSetResponse
            const direction = payload?.enabled ? 'on' : 'off'
            const noun = updated === 1 ? 'insight' : 'insights'
            const extras = [
                unsupported > 0 ? `${unsupported} have no such filter, like SQL insights` : null,
                skipped > 0 ? `${skipped} you can't edit` : null,
            ].filter(Boolean)
            const suffix = extras.length > 0 ? ` Left alone: ${extras.join(', ')}.` : ''
            if (updated > 0) {
                lemonToast.success(`Turned this filter ${direction} for ${updated} ${noun}.${suffix}`)
            } else {
                lemonToast.info(`No insights needed changing.${suffix}`)
            }
        },
        applyToExistingInsightsFailure: () => {
            lemonToast.error('Could not update your existing insights. Try again in a moment.')
        },
    })),
])
